    assert v2 == {"id": 1, "title": "Test", "work_mode": "remote", "version": 2}
    assert v1 == {"id": 1, "name": "Test", "remote": "yes"}  # Check no modification

def test_upgrade_v1_no_remote():
    v1 = {"id": 2, "name": "No Remote"}
    v2 = models.upgrade(v1)
    assert v2 == {"id": 2, "title": "No Remote", "work_mode": "unknown", "version": 2}

def test_upgrade_v1_remote_no():
    v1 = {"id": 3, "name": "Office", "remote": "no"}
    v2 = models.upgrade(v1)
    assert v2 == {"id": 3, "title": "Office", "work_mode": "office", "version": 2}

def test_upgrade_v1_invalid_remote():
    v1 = {"id": 4, "name": "Bad", "remote": "maybe"}
    try:
        models.upgrade(v1)
    except ValueError:
        pass
    else:
        assert False, "Should have raised ValueError for invalid remote"

def test_upgrade_v2_idempotent():
    v2 = {"version": 2, "id": 5, "title": "V2", "work_mode": "remote"}
    v3 = models.upgrade(v2)
    assert v3 == v2
    assert v2 == v3

def test_load_all_mixed():
    rows = [
        {"id": 1, "name": "V1", "remote": "yes"},
        {"version": 2, "id": 2, "title": "V2", "work_mode": "office"}
    ]
    results = storage.load_all(rows)
    assert len(results) == 2
    assert results[0] == {"id": 1, "title": "V1", "work_mode": "remote", "version": 2}
    assert results[1] == {"version": 2, "id": 2, "title": "V2", "work_mode": "office"}

def test_save_v1():
    v1 = {"id": 1, "name": "V1", "remote": "no"}
    v2 = storage.save(v1)
    assert v2 == {"id": 1, "title": "V1", "work_mode": "office", "version": 2}

def test_save_v2():
